var PostsRepository = class {
  async countPosts() {
    const [record] = await db.select({ value: count() }).from(servicePosts);
    return Number(record?.value || 0);
  }
  async findPostsPage(offset, limit) {
    return db.select({
      postId: servicePosts.postId,
      name: servicePosts.name,
      locationDescription: servicePosts.locationDescription,
      openingHours: servicePosts.openingHours,
      directions: servicePosts.directions
    }).from(servicePosts).orderBy(asc(servicePosts.postId)).limit(limit).offset(offset);
  }
  async findPhotosByPostId(postId) {
    return db.select({
      photoId: servicePostPhotos.photoId,
      storagePath: servicePostPhotos.storagePath,
      position: servicePostPhotos.position
    }).from(servicePostPhotos).where(eq(servicePostPhotos.postId, postId)).orderBy(asc(servicePostPhotos.position)).limit(3);
  }
  async findPostById(postId) {
    const [p4] = await db.select({
      postId: servicePosts.postId,
      name: servicePosts.name,
      locationDescription: servicePosts.locationDescription,
      openingHours: servicePosts.openingHours,
      directions: servicePosts.directions
    }).from(servicePosts).where(eq(servicePosts.postId, postId)).limit(1);
    return p4 || null;
  }
};
var postsRepository = new PostsRepository();

// src/utils/photoResolver.ts
function resolvePhotoUrl(storagePath, ttlSeconds = 300) {
  const expiresAtDate = new Date(Date.now() + ttlSeconds * 1e3);
  const expires_at = expiresAtDate.toISOString();
  if (env.R2_PUBLIC_URL && !env.R2_PUBLIC_URL.includes(".r2.dev")) {
    const cleanBase = env.R2_PUBLIC_URL.replace(/\/+$/, "");
    const cleanPath2 = storagePath.replace(/^\/+/, "");
    return {
      url: `${cleanBase}/${cleanPath2}?exp=${Math.floor(expiresAtDate.getTime() / 1e3)}`,
      expires_at
    };
  }
  const cleanPath = storagePath.replace(/^\/+/, "");
  const baseUrl = process.env.VERCEL_URL ? `https://${process.env.VERCEL_URL}` : `http://localhost:${env.PORT}`;
  return {
    url: `${baseUrl}/storage/${cleanPath}?exp=${Math.floor(expiresAtDate.getTime() / 1e3)}`,
    expires_at
  };
}

// src/modules/posts/posts.service.ts
var PostsService = class {
  /**
   * List all service posts with pagination and public photos
   */
  async listPosts({ page, limit }) {
    const offset = (page - 1) * limit;
    const total = await postsRepository.countPosts();
    const total_pages = Math.ceil(total / limit) || (total === 0 ? 0 : 1);
    const postsList = await postsRepository.findPostsPage(offset, limit);
    const data = await Promise.all(
      postsList.map(async (p4) => {
        const photosList = await postsRepository.findPhotosByPostId(p4.postId);
        return this.formatPostResponse(p4, photosList);
      })
    );
    return {
      data,
      meta: { page, limit, total, total_pages }
    };
  }
  /**
   * Get detail of a specific service post by postId
   */
  async getPostById(postId) {
    const p4 = await postsRepository.findPostById(postId);
    if (!p4)
      return null;
    const photosList = await postsRepository.findPhotosByPostId(p4.postId);
    return this.formatPostResponse(p4, photosList);
  }
  formatPostResponse(p4, photosList) {
    const photos = photosList.map((photo) => {
      const resolved = resolvePhotoUrl(photo.storagePath);
      return {
        photo_id: photo.photoId,
        position: photo.position,
        is_cover: photo.position === 1,
        url: resolved.url,
        expires_at: resolved.expires_at
      };
    });
    return {
      post_id: p4.postId,
      name: p4.name,
      location_description: p4.locationDescription,
      opening_hours: p4.openingHours,
      directions: p4.directions,
      photos
    };
  }
};
var postsService = new PostsService();

