var import_crypto = require("crypto");

// src/modules/items/items.repository.ts
var ItemsRepository = class {
  buildFilterConditions(params) {
    const conditions = [
      eq(foundItems.status, "STORED"),
      eq(foundItems.isVisible, true)
    ];
    if (params.post_id !== void 0) {
      conditions.push(eq(foundItems.storagePostId, params.post_id));
    }
    if (params.category && params.category.trim().length > 0) {
      conditions.push(sql`LOWER(${foundItems.category}) = LOWER(${params.category.trim()})`);
    }
    if (params.q && params.q.trim().length > 0) {
      const sanitizedQ = params.q.trim().replace(/[%_\\]/g, "\\$&");
      const pattern = `%${sanitizedQ}%`;
      conditions.push(
        sql`(${foundItems.itemName} ILIKE ${pattern} ESCAPE '\\' OR ${foundItems.publicDescription} ILIKE ${pattern} ESCAPE '\\')`
      );
    }
    return and(...conditions);
  }
  getOrderClauses(sort) {
    if (sort === "received_at_asc") {
      return [asc(foundItems.receivedAt), asc(foundItems.itemId)];
    }
    if (sort === "item_name_asc") {
      return [asc(foundItems.itemName), asc(foundItems.itemId)];
    }
    return [desc(foundItems.receivedAt), asc(foundItems.itemId)];
  }
  async countItems(whereClause) {
    const [totalRecord] = await db.select({ value: count() }).from(foundItems).where(whereClause);
    return Number(totalRecord?.value || 0);
  }
  async findPublicItems(whereClause, orderClauses, offset, limit) {
    return db.select({
      itemId: foundItems.itemId,
      inventoryCode: foundItems.inventoryCode,
      itemName: foundItems.itemName,
      category: foundItems.category,
      publicDescription: foundItems.publicDescription,
      foundLocation: foundItems.foundLocation,
      foundOn: foundItems.foundOn,
      receivedAt: foundItems.receivedAt,
      postId: servicePosts.postId,
      postName: servicePosts.name,
      photoId: itemPhotos.photoId,
      photoStoragePath: itemPhotos.storagePath
    }).from(foundItems).innerJoin(servicePosts, eq(foundItems.storagePostId, servicePosts.postId)).leftJoin(itemPhotos, eq(foundItems.itemId, itemPhotos.itemId)).where(whereClause).orderBy(...orderClauses).limit(limit).offset(offset);
  }
  async findPublicItemById(itemId) {
    const [row] = await db.select({
      itemId: foundItems.itemId,
      inventoryCode: foundItems.inventoryCode,
      itemName: foundItems.itemName,
      category: foundItems.category,
      publicDescription: foundItems.publicDescription,
      foundLocation: foundItems.foundLocation,
      foundOn: foundItems.foundOn,
      receivedAt: foundItems.receivedAt,
      postId: servicePosts.postId,
      postName: servicePosts.name,
      photoId: itemPhotos.photoId,
      photoStoragePath: itemPhotos.storagePath
    }).from(foundItems).innerJoin(servicePosts, eq(foundItems.storagePostId, servicePosts.postId)).leftJoin(itemPhotos, eq(foundItems.itemId, itemPhotos.itemId)).where(
      and(
        eq(foundItems.itemId, itemId),
        eq(foundItems.status, "STORED"),
        eq(foundItems.isVisible, true)
      )
    ).limit(1);
    return row || null;
  }
};
var itemsRepository = new ItemsRepository();

// src/modules/items/items.service.ts
var ItemsService = class {
  /**
   * List public found items with defensive filtering, sorting, pagination, and strict privacy enforcement.
   * Only items with status = 'STORED' AND is_visible = true are ever returned.
   */
  async listPublicItems(params) {
    const { page, limit } = params;
    const offset = (page - 1) * limit;
    const whereClause = itemsRepository.buildFilterConditions(params);
    const orderClauses = itemsRepository.getOrderClauses(params.sort);
    const total = await itemsRepository.countItems(whereClause);
    const total_pages = Math.ceil(total / limit) || (total === 0 ? 0 : 1);
    const rows = await itemsRepository.findPublicItems(whereClause, orderClauses, offset, limit);
    const data = rows.map((row) => this.mapToPublicDto(row));
    return {
      data,
      meta: { page, limit, total, total_pages }
    };
  }
  /**
   * Get public item detail by itemId.
   * Returns null if item is not found, status != 'STORED', or is_visible = false.
   */
  async getPublicItemById(itemId) {
    const row = await itemsRepository.findPublicItemById(itemId);
    if (!row)
      return null;
    return this.mapToPublicDto(row);
  }
  mapToPublicDto(row) {
    const resolved = row.photoStoragePath ? resolvePhotoUrl(row.photoStoragePath) : {
      url: "https://r2.campusfind.local/placeholder.webp",
      expires_at: new Date(Date.now() + 36e5).toISOString()
    };
    return {
      item_id: row.itemId,
      inventory_code: row.inventoryCode,
      item_name: row.itemName,
      category: row.category,
      public_description: row.publicDescription,
      found_location: row.foundLocation,
      found_on: row.foundOn ? String(row.foundOn) : null,
      received_at: row.receivedAt instanceof Date ? row.receivedAt.toISOString() : new Date(row.receivedAt).toISOString(),
      post: {
        post_id: row.postId,
        name: row.postName
      },
      photos: [
        {
          photo_id: row.photoId || (0, import_crypto.randomUUID)(),
          url: resolved.url,
          expires_at: resolved.expires_at,
          is_primary: true
        }
      ]
    };
  }
};
var itemsService = new ItemsService();

