// src/middleware/authenticate.guard.ts
async function authenticate(request, reply) {
  const authHeader = request.headers.authorization;
  if (!authHeader || !authHeader.toLowerCase().startsWith("bearer ")) {
    return reply.status(401).send({
      error: {
        code: "UNAUTHORIZED",
        message: "Token autentikasi tidak ditemukan atau format tidak valid",
        request_id: request.id
      }
    });
  }
  const token = authHeader.slice(7).trim();
  const payload = authService.verifyToken(token);
  if (!payload) {
    return reply.status(401).send({
      error: {
        code: "UNAUTHORIZED",
        message: "Token autentikasi tidak valid atau sudah kedaluwarsa",
        request_id: request.id
      }
    });
  }
  const user = await authService.getUserByAuthId(payload.sub);
  if (!user) {
    return reply.status(404).send({
      error: {
        code: "PROFILE_NOT_FOUND",
        message: "Profil pengguna belum terdaftar dalam sistem",
        request_id: request.id
      }
    });
  }
  request.currentUser = user;
}

// src/middleware/require-officer.guard.ts
async function requireOfficer(request, reply) {
  if (!request.currentUser) {
    await authenticate(request, reply);
    if (reply.sent) {
      return;
    }
  }
  const user = request.currentUser;
  if (user.role !== "OFFICER") {
    return reply.status(403).send({
      error: {
        code: "FORBIDDEN",
        message: "Akses ditolak: Hanya petugas (OFFICER) yang berhak mengakses layanan ini",
        request_id: request.id
      }
    });
  }
  const post = await authService.getOfficerPost(user.userId);
  if (!post) {
    return reply.status(403).send({
      error: {
        code: "FORBIDDEN",
        message: "Petugas belum memiliki pos penugasan aktif",
        request_id: request.id
      }
    });
  }
  request.officerContext = {
    user,
    postId: post.postId,
    postName: post.name
  };
}

// src/middleware/require-student.guard.ts
async function requireStudent(request, reply) {
  if (!request.currentUser) {
    await authenticate(request, reply);
    if (reply.sent) {
      return;
    }
  }
  const user = request.currentUser;
  if (user.role !== "STUDENT") {
    return reply.status(403).send({
      error: {
        code: "FORBIDDEN",
        message: "Akses ditolak: Hanya mahasiswa (STUDENT) yang berhak mengakses layanan ini",
        request_id: request.id
      }
    });
  }
}

